  "A bureau does not observe your accounts directly. It compiles what lenders submit, usually monthly.": "ବ୍ୟୁରୋ ଆପଣଙ୍କ ଖାତାକୁ ସିଧାସଳଖ ଦେଖେ ନାହିଁ। ଏହା ଋଣଦାତାମାନେ ଦାଖଲ କରୁଥିବା ତଥ୍ୟ, ସାଧାରଣତଃ ମାସିକ, ସଙ୍କଳନ କରେ।",
  "A buy–sell spread applies, so the price you can sell at is below the price you buy at.": "କ୍ରୟ–ବିକ୍ରୟ ବ୍ୟବଧାନ ଲାଗୁ ହୁଏ, ତେଣୁ ବିକ୍ରୟ ମୂଲ୍ୟ କ୍ରୟ ମୂଲ୍ୟଠାରୁ କମ ରହେ।",
