  "A claim is paid to the nominee — keep nomination details current.": "ଦାବି ନାମିନିଙ୍କୁ ଦିଆଯାଏ — ମନୋନୟନ ବିବରଣୀ ଅଦ୍ୟତନ ରଖନ୍ତୁ।",
  "A clean repayment record helps build credit history": "ସ୍ୱଚ୍ଛ ପରିଶୋଧ ରେକର୍ଡ କ୍ରେଡିଟ ଇତିହାସ ଗଢ଼ିବାରେ ସାହାଯ୍ୟ କରେ",
  "A clear view of your active borrowing and repayment progress.": "ଆପଣଙ୍କ ସକ୍ରିୟ ଋଣ ଓ ପରିଶୋଧ ପ୍ରଗତିର ସ୍ପଷ୍ଟ ଚିତ୍ର।",
  "A common starting point is a multiple of annual income, adjusted for debts and dependants’ needs. Your own circumstances decide it.": "ଏକ ସାଧାରଣ ଆରମ୍ଭ ବିନ୍ଦୁ ହେଉଛି ବାର୍ଷିକ ଆୟର ଗୁଣିତକ, ଋଣ ଓ ନିର୍ଭରଶୀଳଙ୍କ ଆବଶ୍ୟକତା ଅନୁସାରେ ସମନ୍ୱିତ। ଆପଣଙ୍କ ନିଜ ପରିସ୍ଥିତି ହିଁ ସ୍ଥିର କରେ।",
  "A conservative share of land value": "ଜମି ମୂଲ୍ୟର ଏକ ସୀମିତ ଅଂଶ",
  "A daily list of the biggest movers. Sharp single-day moves often reflect news specific to one company rather than a trend.": "ସବୁଠାରୁ ଅଧିକ ଉଠାଣି-ପଡ଼ାଣିର ଦୈନିକ ତାଲିକା। ଏକ ଦିନର ତୀବ୍ର ଗତିବିଧି ପ୍ରାୟତଃ କୌଣସି ଧାରା ନୁହେଁ, ଏକ ନିର୍ଦ୍ଦିଷ୍ଟ କମ୍ପାନୀର ଖବର ପ୍ରତିଫଳିତ କରେ।",
  "A dedicated advisor reads your profile, flags what will and will not get approved, and shapes the application before it goes out.": "ଜଣେ ସମର୍ପିତ ପରାମର୍ଶଦାତା ଆପଣଙ୍କ ପ୍ରୋଫାଇଲ ପଢ଼ନ୍ତି, କ’ଣ ଅନୁମୋଦିତ ହେବ ଓ କ’ଣ ନୁହେଁ ଚିହ୍ନଟ କରନ୍ତି, ଓ ପଠାଇବା ପୂର୍ବରୁ ଆବେଦନକୁ ଗଢ଼ନ୍ତି।",
  "A defined return over a defined term — the reference point most other products are judged against.": "ନିର୍ଦ୍ଦିଷ୍ଟ ଅବଧିରେ ନିର୍ଦ୍ଦିଷ୍ଟ ପ୍ରତିଫଳ — ସେହି ସନ୍ଦର୍ଭ ବିନ୍ଦୁ ଯାହା ସହିତ ଅଧିକାଂଶ ଅନ୍ୟ ଉତ୍ପାଦ ତୁଳନା କରାଯାଏ।",
  "A digital-first loan for borrowers with a ready credit profile.": "ପ୍ରସ୍ତୁତ କ୍ରେଡିଟ ପ୍ରୋଫାଇଲ ଥିବା ଋଣଗ୍ରହୀତାଙ୍କ ପାଇଁ ଡିଜିଟାଲ-ପ୍ରଥମ ଋଣ।",
  "A documented plan with realistic projections": "ବାସ୍ତବବାଦୀ ଅନୁମାନ ସହିତ ଦଲିଲଭୁକ୍ତ ଯୋଜନା",
  "A fall in gold prices can trigger a margin call requiring you to pay down or pledge more": "ସୁନା ମୂଲ୍ୟ ପଡ଼ିଲେ ମାର୍ଜିନ କଲ ଆସିପାରେ, ଯେଉଁଥିରେ ଆପଣଙ୍କୁ ଟଙ୍କା ଦେବାକୁ କିମ୍ବା ଅଧିକ ବନ୍ଧକ ରଖିବାକୁ ପଡ଼େ",
  "A floating rate can rise — a small change over 20 years is a large sum": "ପରିବର୍ତ୍ତନଶୀଳ ହାର ବଢ଼ିପାରେ — 20 ବର୍ଷରେ ଛୋଟ ପରିବର୍ତ୍ତନ ମଧ୍ୟ ବଡ଼ ରାଶି ହୁଏ",
