  "Add every upfront charge": "ପ୍ରତ୍ୟେକ ଅଗ୍ରୀମ ଶୁଳ୍କ ଯୋଡ଼ନ୍ତୁ",
  "Add GST to a net price, or strip it out of a gross price.": "ନିଟ୍ ମୂଲ୍ୟରେ GST ଯୋଡ଼ନ୍ତୁ, କିମ୍ବା ମୋଟ ମୂଲ୍ୟରୁ ବାଦ ଦିଅନ୍ତୁ।",
  "Add the processing fee": "ପ୍ରକ୍ରିୟାକରଣ ଶୁଳ୍କ ଯୋଡ଼ନ୍ତୁ",
  "Add-ons such as engine protection and roadside assistance, each priced separately.": "ଇଞ୍ଜିନ ସୁରକ୍ଷା ଓ ରୋଡସାଇଡ ସହାୟତା ପରି ଆଡ-ଅନ, ପ୍ରତ୍ୟେକର ମୂଲ୍ୟ ଅଲଗା।",
  "Adding a floor to an existing home": "ବର୍ତ୍ତମାନର ଘରରେ ମହଲା ଯୋଡ଼ିବା",
  "Adding a second family vehicle": "ଦ୍ୱିତୀୟ ପାରିବାରିକ ଯାନ ଯୋଡ଼ିବା",
