  "Borrowers whose rate has drifted above current market rates": "ଯାହାଙ୍କ ହାର ବର୍ତ୍ତମାନ ବଜାର ହାରଠାରୁ ଉପରକୁ ଯାଇଛି ଏମିତି ଋଣଗ୍ରହୀତା",
  "Borrowers with an approved plan and cost estimate": "ଅନୁମୋଦିତ ଯୋଜନା ଓ ଖର୍ଚ୍ଚ ଆକଳନ ଥିବା ଋଣଗ୍ରହୀତା",
  "Borrowers with an urgent, short-term need": "ଜରୁରୀ, ସ୍ୱଳ୍ପକାଳୀନ ଆବଶ୍ୟକତା ଥିବା ଋଣଗ୍ରହୀତା",
  "Borrowers with clean credit history and verifiable digital records": "ସ୍ୱଚ୍ଛ କ୍ରେଡିଟ ଇତିହାସ ଓ ଯାଞ୍ଚଯୋଗ୍ୟ ଡିଜିଟାଲ ରେକର୍ଡ ଥିବା ଋଣଗ୍ରହୀତା",
