  "Compare all rates": "ସମସ୍ତ ହାର ତୁଳନା କରନ୍ତୁ",
  "Compare available options on rate, fees, tenure and total cost.": "ହାର, ଶୁଳ୍କ, ଅବଧି ଓ ମୋଟ ଖର୍ଚ୍ଚରେ ଉପଲବ୍ଧ ବିକଳ୍ପ ତୁଳନା କରନ୍ତୁ।",
  "Compare it against the open market — a pre-approved offer is convenient, not automatically competitive.": "ଏହାକୁ ଖୋଲା ବଜାର ସହ ତୁଳନା କରନ୍ତୁ — ପୂର୍ବ-ଅନୁମୋଦିତ ଅଫର ସୁବିଧାଜନକ, ସ୍ୱତଃ ପ୍ରତିଯୋଗିତାମୂଳକ ନୁହେଁ।",
  "Compare lenders": "ଋଣଦାତାଙ୍କ ତୁଳନା କରନ୍ତୁ",
