  "Compare rates": "ହାର ତୁଳନା କରନ୍ତୁ",
  "Compare the cost against simply increasing your term life cover.": "ଏହାର ଖର୍ଚ୍ଚକୁ ଆପଣଙ୍କ ଟର୍ମ ଲାଇଫ କଭର ବଢ଼ାଇବା ସହ ତୁଳନା କରନ୍ତୁ।",
  "Compare the dealer’s finance against an independent lender before signing": "ସ୍ୱାକ୍ଷର ପୂର୍ବରୁ ଡିଲରଙ୍କ ଅର୍ଥକୁ ସ୍ୱାଧୀନ ଋଣଦାତାଙ୍କ ସହ ତୁଳନା କରନ୍ତୁ",
  "Compare the exit terms": "ପ୍ରସ୍ଥାନ ସର୍ତ୍ତ ତୁଳନା କରନ୍ତୁ",
  "Compare the rate against a standard gold loan — speed is sometimes priced in": "ହାରକୁ ସାଧାରଣ ସୁନା ଋଣ ସହ ତୁଳନା କରନ୍ତୁ — ଦ୍ରୁତତାର ମୂଲ୍ୟ ବେଳେବେଳେ ଯୋଡ଼ାଥାଏ",
  "Compare the total cost of borrowing, not the monthly instalment alone.": "ଋଣର ମୋଟ ଖର୍ଚ୍ଚ ତୁଳନା କରନ୍ତୁ, କେବଳ ମାସିକ କିସ୍ତିର ନୁହେଁ।",
  "Compare total payable, not the EMI": "EMI ନୁହେଁ, ମୋଟ ଦେୟ ତୁଳନା କରନ୍ତୁ",
  "Compared six lenders for working capital and picked the one with the lowest processing fee. The fee breakdown alone saved me ₹40,000.": "କାର୍ଯ୍ୟକାରୀ ପୁଞ୍ଜି ପାଇଁ ଛଅ ଋଣଦାତାଙ୍କୁ ତୁଳନା କରି ସର୍ବନିମ୍ନ ପ୍ରୋସେସିଂ ଶୁଳ୍କ ଥିବାଟି ବାଛିଲି। କେବଳ ଶୁଳ୍କ ବିଭାଜନ ମୋର ₹40,000 ସଞ୍ଚୟ କଲା।",
  "Comparing properly": "ଠିକ୍ ଭାବରେ ତୁଳନା",
  "Comparing six lenders took minutes, and the fee breakdown showed the cheapest headline rate was not the cheapest loan.": "ଛଅ ଋଣଦାତାଙ୍କ ତୁଳନାରେ ମିନିଟ ଲାଗିଲା, ଓ ଶୁଳ୍କ ବିଭାଜନ ଦେଖାଇଲା ଯେ ସର୍ବନିମ୍ନ ମୁଖ୍ୟ ହାର ସବୁଠାରୁ ଶସ୍ତା ଋଣ ନଥିଲା।",
  "Comparison gets you a shortlist. These are the services that get the loan actually sanctioned, at a price worth signing for.": "ତୁଳନା ଆପଣଙ୍କୁ ଏକ ସଂକ୍ଷିପ୍ତ ତାଲିକା ଦିଏ। ଏଗୁଡ଼ିକ ହିଁ ସେହି ସେବା ଯାହା ଋଣକୁ ପ୍ରକୃତରେ ମଞ୍ଜୁର କରାଏ, ଏପରି ମୂଲ୍ୟରେ ଯେଉଁଥିରେ ଦସ୍ତଖତ କରିବା ଉପଯୁକ୍ତ।",
  "Comparison is meaningless otherwise.": "ନଚେତ୍ ତୁଳନା ଅର୍ଥହୀନ।",
