  "Compounded quarterly. Interest on FDs is taxable at your slab rate.": "ତ୍ରୈମାସିକ ଚକ୍ରବୃଦ୍ଧି। FD ର ସୁଧ ଆପଣଙ୍କ ସ୍ଲାବ ହାରରେ କରଯୋଗ୍ୟ।",
  "Compounding frequency": "ଚକ୍ରବୃଦ୍ଧି ଆବୃତ୍ତି",
  "Comprehensive": "ବ୍ୟାପକ",
  "Comprehensive cover for medical expenses.": "ଚିକିତ୍ସା ଖର୍ଚ୍ଚ ପାଇଁ ବ୍ୟାପକ କଭର।",
  "Concentrated single-stock holdings may attract steeper haircuts": "ଏକକ ଶେୟାରରେ ଏକାଗ୍ର ହୋଲ୍ଡିଂରେ ଅଧିକ ହେୟାରକଟ ଲାଗିପାରେ",
  "Concentration": "ଏକାଗ୍ରତା",
  "Condition and service history matter — get an independent inspection": "ଅବସ୍ଥା ଓ ସର୍ଭିସ ଇତିହାସ ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ — ସ୍ୱାଧୀନ ପରିଦର୍ଶନ କରାନ୍ତୁ",
  "Confirm each one is yours, and that closed accounts show as closed.": "ନିଶ୍ଚିତ କରନ୍ତୁ ପ୍ରତ୍ୟେକଟି ଆପଣଙ୍କର, ଓ ବନ୍ଦ ଖାତା ବନ୍ଦ ଭାବରେ ଦେଖାଯାଏ।",
  "Confirm new password": "ନୂଆ ପାସୱାର୍ଡ ନିଶ୍ଚିତ କରନ୍ତୁ",
