  "Confirm the rate is fixed at that level for your profile, in writing.": "ଆପଣଙ୍କ ପ୍ରୋଫାଇଲ ପାଇଁ ହାର ସେହି ସ୍ତରରେ ସ୍ଥିର ବୋଲି ଲିଖିତ ଭାବରେ ନିଶ୍ଚିତ କରନ୍ତୁ।",
  "Confirm the rate, tenure, EMI, all fees and the foreclosure terms in writing.": "ହାର, ଅବଧି, EMI, ସମସ୍ତ ଶୁଳ୍କ ଓ ଅଗ୍ରୀମ ସମାପ୍ତି ସର୍ତ୍ତ ଲିଖିତ ଭାବରେ ନିଶ୍ଚିତ କରନ୍ତୁ।",
  "Confirm what happens to the cover if you prepay or transfer the loan.": "ପୂର୍ବ ପରିଶୋଧ କିମ୍ବା ସ୍ଥାନାନ୍ତରରେ କଭରର କ’ଣ ହୁଏ ନିଶ୍ଚିତ କରନ୍ତୁ।",
  "Confirm whether the amount continues to block your credit limit.": "ନିଶ୍ଚିତ କରନ୍ତୁ ରାଶି ଆପଣଙ୍କ କ୍ରେଡିଟ ସୀମା ଅଟକାଇ ରଖେ କି।",
  "Confirm who holds the gold, how it is insured, and how redemption works before buying.": "କିଣିବା ପୂର୍ବରୁ ନିଶ୍ଚିତ କରନ୍ତୁ ସୁନା କିଏ ରଖେ, ତାହାର ବୀମା କିପରି, ଓ ମୋଚନ କିପରି ହୁଏ।",
  "Confirmed admission to a recognised institution": "ମାନ୍ୟତାପ୍ରାପ୍ତ ଅନୁଷ୍ଠାନରେ ନିଶ୍ଚିତ ପ୍ରବେଶ",
