  "Contact Us": "ଯୋଗାଯୋଗ କରନ୍ତୁ",
  "Context for why prices moved. Useful for understanding; a poor basis for reacting.": "ମୂଲ୍ୟ କାହିଁକି ବଦଳିଲା ତାହାର ପ୍ରସଙ୍ଗ। ବୁଝିବା ପାଇଁ ଉପଯୋଗୀ; ପ୍ରତିକ୍ରିୟାର ଦୁର୍ବଳ ଆଧାର।",
