  "Contractors with committed haulage work": "ନିଶ୍ଚିତ ପରିବହନ କାମ ଥିବା ଠିକାଦାର",
  "Contracts or freight agreements, if available": "ଉପଲବ୍ଧ ଥିଲେ ଚୁକ୍ତି କିମ୍ବା ମାଲ ପରିବହନ ଚୁକ୍ତି",
  "Contracts or work orders": "ଚୁକ୍ତି କିମ୍ବା କାର୍ଯ୍ୟାଦେଶ",
  "Convenience is sometimes priced in; compare the rate against a standard personal loan": "ସୁବିଧାର ମୂଲ୍ୟ ବେଳେବେଳେ ହାରରେ ଯୋଡ଼ାଯାଏ; ଏହାକୁ ସାଧାରଣ ବ୍ୟକ୍ତିଗତ ଋଣ ସହିତ ତୁଳନା କରନ୍ତୁ",
  "Convenient, but usually carries a foreign-currency mark-up in addition to the exchange rate.": "ସୁବିଧାଜନକ, କିନ୍ତୁ ସାଧାରଣତଃ ବିନିମୟ ହାର ବ୍ୟତୀତ ବିଦେଶୀ ମୁଦ୍ରା ମାର୍କ-ଅପ ମଧ୍ୟ ଲାଗେ।",
  "Converting a purchase into instalments — and what that conversion actually costs.": "କ୍ରୟକୁ କିସ୍ତିରେ ପରିଣତ କରିବା — ଓ ସେହି ରୂପାନ୍ତରର ପ୍ରକୃତ ଖର୍ଚ୍ଚ କେତେ।",
  "Converting an existing card transaction into instalments after the purchase. The limit stays blocked until repaid.": "କ୍ରୟ ପରେ ବିଦ୍ୟମାନ କାର୍ଡ କାରବାରକୁ କିସ୍ତିରେ ରୂପାନ୍ତର କରିବା। ପରିଶୋଧ ନ ହେବା ପର୍ଯ୍ୟନ୍ତ ସୀମା ଅବରୋଧିତ ରହେ।",
  "Converts an illiquid asset into working funds without selling it": "ଅତରଳ ସମ୍ପତ୍ତିକୁ ନ ବିକ୍ରି କରି କାର୍ଯ୍ୟକାରୀ ଟଙ୍କାରେ ପରିଣତ କରେ",
  "Corpus at 60": "60 ବର୍ଷରେ କର୍ପସ",
