  "Cost per rupee borrowed can be high on small, short loans": "ଛୋଟ, ସ୍ୱଳ୍ପକାଳୀନ ଋଣରେ ପ୍ରତି ଟଙ୍କାରେ ଖର୍ଚ୍ଚ ଅଧିକ ହୋଇପାରେ",
  "Cost per rupee borrowed can be high on very short tenures — always check the total, not just the fee": "ଅତି ଛୋଟ ଅବଧିରେ ପ୍ରତି ଟଙ୍କା ଋଣର ଖର୍ଚ୍ଚ ଅଧିକ ହୋଇପାରେ — ସର୍ବଦା ମୋଟ ଦେଖନ୍ତୁ, କେବଳ ଶୁଳ୍କ ନୁହେଁ",
