  "Driving licence": "ଡ୍ରାଇଭିଂ ଲାଇସେନ୍ସ",
  "Due 10 Sep 2026": "ଦେୟ 10 ସେପ୍ଟେମ୍ବର 2026",
  "Duration": "ଅବଧି",
  "Duration (years)": "ଅବଧି (ବର୍ଷ)",
  "Each bureau uses its own model and may hold slightly different data, so scores can differ. None is the single official number.": "ପ୍ରତ୍ୟେକ ବ୍ୟୁରୋ ନିଜ ମଡେଲ ବ୍ୟବହାର କରେ ଓ ତାହା ପାଖରେ ଟିକେ ଭିନ୍ନ ତଥ୍ୟ ଥାଇପାରେ, ତେଣୁ ସ୍କୋର ଭିନ୍ନ ହୋଇପାରେ। କୌଣସିଟି ଏକମାତ୍ର ସରକାରୀ ସଂଖ୍ୟା ନୁହେଁ।",
  "Each credit information company has a dispute process. Submit the specific entry and your evidence.": "ପ୍ରତ୍ୟେକ କ୍ରେଡିଟ ସୂଚନା କମ୍ପାନୀର ଏକ ବିବାଦ ପ୍ରକ୍ରିୟା ଅଛି। ନିର୍ଦ୍ଦିଷ୍ଟ ଏଣ୍ଟ୍ରି ଓ ଆପଣଙ୍କ ପ୍ରମାଣ ଦାଖଲ କରନ୍ତୁ।",
  "Each lender publishes an approved list with its own advance rates. Debt funds usually qualify for a higher proportion than equity funds.": "ପ୍ରତ୍ୟେକ ଋଣଦାତା ନିଜ ଅଗ୍ରିମ ହାର ସହିତ ଅନୁମୋଦିତ ତାଲିକା ପ୍ରକାଶ କରନ୍ତି। ଡେଟ ଫଣ୍ଡ ସାଧାରଣତଃ ଇକ୍ୱିଟି ଫଣ୍ଡଠାରୁ ଅଧିକ ଅନୁପାତ ପାଇଁ ଯୋଗ୍ୟ।",
  "Early working capital": "ପ୍ରାରମ୍ଭିକ କାର୍ଯ୍ୟକାରୀ ପୁଞ୍ଜି",
  "Early-stage finance where trading history is limited.": "ସୀମିତ ବ୍ୟବସାୟ ଇତିହାସ ଥିବା ପ୍ରାରମ୍ଭିକ ପର୍ଯ୍ୟାୟର ଅର୍ଥ।",
  "Earn miles or points, sometimes with lounge access. Worth the fee only if you genuinely use the benefits.": "ମାଇଲ କିମ୍ବା ପଏଣ୍ଟ ଅର୍ଜନ କରନ୍ତୁ, ବେଳେବେଳେ ଲାଉଞ୍ଜ ସୁବିଧା ସହିତ। ଶୁଳ୍କ ସେତେବେଳେ ହିଁ ଉପଯୁକ୍ତ ଯେତେବେଳେ ଆପଣ ସୁବିଧା ପ୍ରକୃତରେ ବ୍ୟବହାର କରନ୍ତି।",
