  "Equity funds qualifying for deduction under Section 80C, with a three-year lock-in — the shortest among 80C options.": "ଧାରା 80C ଅଧୀନରେ ଛାଡ଼ ପାଇଁ ଯୋଗ୍ୟ ଇକ୍ୱିଟି ଫଣ୍ଡ, ତିନି ବର୍ଷର ଲକ-ଇନ ସହିତ — 80C ବିକଳ୍ପ ମଧ୍ୟରେ ସର୍ବନିମ୍ନ।",
