  "Every fee, penalty and add-on is shown before you accept, in writing.": "ପ୍ରତ୍ୟେକ ଶୁଳ୍କ, ଜରିମାନା ଓ ଆଡ-ଅନ ଗ୍ରହଣ ପୂର୍ବରୁ ଲିଖିତ ଭାବରେ ଦେଖାଯାଏ।",
  "Every hard enquiry made when you applied for credit, with the lender and date.": "ଋଣ ଆବେଦନ ସମୟରେ କରାଯାଇଥିବା ପ୍ରତ୍ୟେକ ହାର୍ଡ ଅନୁସନ୍ଧାନ, ଋଣଦାତା ଓ ତାରିଖ ସହିତ।",
  "Every loan and card, with sanctioned amount, outstanding balance, and whether the account is open or closed.": "ପ୍ରତ୍ୟେକ ଋଣ ଓ କାର୍ଡ, ମଞ୍ଜୁର ରାଶି, ବକେୟା ବାଲାନ୍ସ, ଓ ଖାତା ଖୋଲା ଅଛି ନା ବନ୍ଦ ସହିତ।",
  "Every loan we broker, with real starting rates": "ଆମର ପ୍ରତ୍ୟେକ ଋଣ, ପ୍ରକୃତ ଆରମ୍ଭ ହାର ସହିତ",
  "Every partner is RBI-registered. We route your application to the ones whose credit policy actually fits your profile.": "ପ୍ରତ୍ୟେକ ସହଭାଗୀ RBI-ପଞ୍ଜୀକୃତ। ଆମେ ଆପଣଙ୍କ ଆବେଦନ ସେମାନଙ୍କ ପାଖକୁ ପଠାଉ ଯେଉଁମାନଙ୍କ କ୍ରେଡିଟ ନୀତି ପ୍ରକୃତରେ ଆପଣଙ୍କ ପ୍ରୋଫାଇଲ ସହ ମେଳ ଖାଏ।",
  "Every product page sets out what it is, who it suits and what to weigh up, in plain English.": "ପ୍ରତ୍ୟେକ ଉତ୍ପାଦ ପୃଷ୍ଠା ସରଳ ଭାଷାରେ କୁହେ ତାହା କ’ଣ, କାହା ପାଇଁ ଉପଯୁକ୍ତ ଓ କ’ଣ ବିଚାର କରିବାକୁ ହେବ।",
  "Every term that turns up on a sanction letter or offer document, in plain English.": "ଅନୁମୋଦନ ପତ୍ର କିମ୍ବା ଅଫର ଦଲିଲରେ ଆସୁଥିବା ପ୍ରତ୍ୟେକ ଶବ୍ଦ, ସରଳ ଭାଷାରେ।",
  "Excellent": "ଉତ୍କୃଷ୍ଟ",
  "Exchange rate margin": "ବିନିମୟ ହାର ମାର୍ଜିନ",
  "Exchange-traded or fund routes, held in demat or a folio, regulated by SEBI.": "ଏକ୍ସଚେଞ୍ଜ-ଟ୍ରେଡେଡ କିମ୍ବା ଫଣ୍ଡ ମାର୍ଗ, ଡିମ୍ୟାଟ କିମ୍ବା ଫୋଲିଓରେ ରଖା, SEBI ନିୟନ୍ତ୍ରିତ।",
  "Exclusions — read this section first, not last.": "ବର୍ଜନ — ଏହି ବିଭାଗ ପ୍ରଥମେ ପଢ଼ନ୍ତୁ, ଶେଷରେ ନୁହେଁ।",
  "Exclusions for adventure sports and high-risk activities.": "ସାହସିକ କ୍ରୀଡ଼ା ଓ ଉଚ୍ଚ-ବିପଦ କାର୍ଯ୍ୟକଳାପ ପାଇଁ ବର୍ଜନ।",
  "Existing customers of a lender who already hold their KYC": "ଋଣଦାତାଙ୍କ ବର୍ତ୍ତମାନର ଗ୍ରାହକ ଯାହାଙ୍କ KYC ପୂର୍ବରୁ ଅଛି",
  "Existing debts should be current — arrears make approval harder": "ବର୍ତ୍ତମାନର ଋଣ ଅଦ୍ୟତନ ରହିବା ଉଚିତ — ବକେୟା ଅନୁମୋଦନ କଠିନ କରେ",
  "Existing EMI": "ବର୍ତ୍ତମାନର EMI",
  "Existing EMI (₹)": "ବର୍ତ୍ତମାନର EMI (₹)",
  "Existing EMIs": "ବର୍ତ୍ତମାନର EMI",
