  "Existing fleet registration documents": "ବର୍ତ୍ତମାନର ଫ୍ଲିଟର ପଞ୍ଜୀକରଣ ଦଲିଲ",
  "Existing home loan borrowers with a clean record": "ସ୍ୱଚ୍ଛ ରେକର୍ଡ ଥିବା ବର୍ତ୍ତମାନର ଗୃହ ଋଣ ଗ୍ରହୀତା",
  "Existing home loan on the property reduces what can be raised": "ସମ୍ପତ୍ତିରେ ବର୍ତ୍ତମାନର ଗୃହ ଋଣ ଉଠାଯାଇପାରୁଥିବା ରାଶି କମାଏ",
