  "Existing loan account statement and sanction letter": "ବର୍ତ୍ତମାନର ଋଣ ଖାତା ବିବରଣୀ ଓ ଅନୁମୋଦନ ପତ୍ର",
  "Existing loan statement and repayment record": "ବର୍ତ୍ତମାନର ଋଣ ବିବରଣୀ ଓ ପରିଶୋଧ ରେକର୍ଡ",
  "Existing vehicle registration and permits": "ବର୍ତ୍ତମାନର ଯାନ ପଞ୍ଜୀକରଣ ଓ ପରମିଟ",
  "Exit load and lock-in, which determine what it costs to leave early.": "ଏକ୍ସିଟ ଲୋଡ ଓ ଲକ-ଇନ, ଯାହା ଶୀଘ୍ର ବାହାରିବାର ଖର୍ଚ୍ଚ ନିର୍ଦ୍ଧାରଣ କରେ।",
  "Expansion or a second location": "ବିସ୍ତାର କିମ୍ବା ଦ୍ୱିତୀୟ ସ୍ଥାନ",
