  "Expected return (% p.a.)": "ଆଶାକରାଯାଉଥିବା ରିଟର୍ଣ୍ଣ (% ବାର୍ଷିକ)",
  "Experience in the transport trade, as required by the lender": "ଋଣଦାତାଙ୍କ ଆବଶ୍ୟକତା ଅନୁଯାୟୀ ପରିବହନ ବ୍ୟବସାୟରେ ଅଭିଜ୍ଞତା",
  "Explain, don’t sell": "ବୁଝାନ୍ତୁ, ବିକ୍ରି କରନ୍ତୁ ନାହିଁ",
