  "Explore and compare available rates.": "ଉପଲବ୍ଧ ହାର ଦେଖନ୍ତୁ ଓ ତୁଳନା କରନ୍ତୁ।",
  "Explore loan options, compare costs, calculate your EMI, and understand your choices before you apply.": "ଆବେଦନ ପୂର୍ବରୁ ଋଣ ବିକଳ୍ପ ଦେଖନ୍ତୁ, ଖର୍ଚ୍ଚ ତୁଳନା କରନ୍ତୁ, EMI ଗଣନା କରନ୍ତୁ ଓ ଆପଣଙ୍କ ପସନ୍ଦ ବୁଝନ୍ତୁ।",
