  "Families building to their own design": "ନିଜ ଡିଜାଇନରେ ନିର୍ମାଣ କରୁଥିବା ପରିବାର",
  "Families facing hospitalisation costs above their cover": "କଭରଠାରୁ ଅଧିକ ଡାକ୍ତରଖାନା ଖର୍ଚ୍ଚର ସମ୍ମୁଖୀନ ପରିବାର",
  "Families funding education, medical or business needs": "ଶିକ୍ଷା, ଚିକିତ୍ସା କିମ୍ବା ବ୍ୟବସାୟିକ ଆବଶ୍ୟକତା ପୂରଣ କରୁଥିବା ପରିବାର",
  "Families managing wedding costs across a short window": "ଅଳ୍ପ ସମୟରେ ବିବାହ ଖର୍ଚ୍ଚ ସମ୍ଭାଳୁଥିବା ପରିବାର",
  "Families planning a milestone trip": "ବିଶେଷ ଯାତ୍ରା ଯୋଜନା କରୁଥିବା ପରିବାର",
  "Families relocating or upgrading": "ସ୍ଥାନାନ୍ତର କିମ୍ବା ଉନ୍ନତି କରୁଥିବା ପରିବାର",
  "Families upgrading to a larger home": "ବଡ଼ ଘରକୁ ଯାଉଥିବା ପରିବାର",
