  "Families with inherited or unused ornaments": "ଉତ୍ତରାଧିକାରରେ ମିଳିଥିବା କିମ୍ବା ଅବ୍ୟବହୃତ ଅଳଙ୍କାର ଥିବା ପରିବାର",
