  "Fees, prepayment terms and the things that can go wrong are stated, not buried.": "ଶୁଳ୍କ, ପୂର୍ବ ପରିଶୋଧ ସର୍ତ୍ତ ଓ ଯାହା ଭୁଲ ହୋଇପାରେ ସବୁ ସ୍ପଷ୍ଟ ଲେଖା, ଲୁଚାଯାଇ ନାହିଁ।",
