  "Finance aimed at micro, small and medium enterprises.": "କ୍ଷୁଦ୍ର, ଛୋଟ ଓ ମଧ୍ୟମ ଉଦ୍ୟୋଗ ପାଇଁ ଅର୍ଥ।",
  "Finance for a brand-new car.": "ଏକଦମ ନୂଆ କାର ପାଇଁ ଅର୍ଥ।",
