  "Manufacturers and service businesses within MSME thresholds": "MSME ସୀମା ମଧ୍ୟରେ ଉତ୍ପାଦକ ଓ ସେବା ବ୍ୟବସାୟ",
  "Many lenders decline agricultural land outright": "ଅନେକ ଋଣଦାତା କୃଷି ଜମି ସିଧାସଳଖ ପ୍ରତ୍ୟାଖ୍ୟାନ କରନ୍ତି",
  "Many lenders disburse within the same visit once valuation and KYC are complete. No lender guarantees a specific time.": "ମୂଲ୍ୟାଙ୍କନ ଓ KYC ସମ୍ପୂର୍ଣ୍ଣ ହେଲେ ଅନେକ ଋଣଦାତା ସେହି ପରିଦର୍ଶନରେ ହିଁ ବଣ୍ଟନ କରନ୍ତି। କୌଣସି ଋଣଦାତା ନିର୍ଦ୍ଦିଷ୍ଟ ସମୟର ଗ୍ୟାରେଣ୍ଟି ଦିଅନ୍ତି ନାହିଁ।",
  "Many lenders maintain lists of recognised institutions, with better terms for those on them.": "ଅନେକ ଋଣଦାତା ମାନ୍ୟତାପ୍ରାପ୍ତ ସଂସ୍ଥାର ତାଲିକା ରଖନ୍ତି, ସେଥିରେ ଥିବା ସଂସ୍ଥା ପାଇଁ ସର୍ତ୍ତ ଭଲ।",
