  "Margin contribution from own funds, as set by the lender": "ଋଣଦାତାଙ୍କ ଦ୍ୱାରା ନିର୍ଦ୍ଧାରିତ ନିଜ ପାଣ୍ଠିରୁ ମାର୍ଜିନ ଅବଦାନ",
  "Margin trading facility": "ମାର୍ଜିନ ଟ୍ରେଡିଂ ସୁବିଧା",
  "Market news": "ବଜାର ଖବର",
  "Market returns are not guaranteed and vary year to year. This is an assumption you set, not a projection.": "ବଜାର ପ୍ରତିଫଳର ଗ୍ୟାରେଣ୍ଟି ନାହିଁ ଓ ତାହା ବର୍ଷକୁ ବର୍ଷ ବଦଳେ। ଏହା ଆପଣ ସ୍ଥିର କରିଥିବା ଅନୁମାନ, ପୂର୍ବାନୁମାନ ନୁହେଁ।",
  "Market risk disclosure": "ବଜାର ବିପଦ ପ୍ରକଟୀକରଣ",
