  "No-cost EMI": "ନୋ-କଷ୍ଟ EMI",
  "No. A guarantee protects the lender against loss. You remain fully liable for repaying the loan.": "ନା। ଗ୍ୟାରେଣ୍ଟି ଋଣଦାତାଙ୍କୁ କ୍ଷତିରୁ ରକ୍ଷା କରେ। ଋଣ ପରିଶୋଧର ସମ୍ପୂର୍ଣ୍ଣ ଦାୟିତ୍ୱ ଆପଣଙ୍କର ହିଁ ରହେ।",
  "No. A lower rate with a high processing fee or a longer tenure can cost more overall. Compare the total amount repayable.": "ନା। ଅଧିକ ପ୍ରୋସେସିଂ ଶୁଳ୍କ କିମ୍ବା ଦୀର୍ଘ ଅବଧି ସହିତ କମ ହାର ସାମଗ୍ରିକ ଭାବରେ ମହଙ୍ଗା ପଡ଼ିପାରେ। ମୋଟ ପରିଶୋଧଯୋଗ୍ୟ ରାଶି ତୁଳନା କରନ୍ତୁ।",
  "No. Checking your own report is a soft enquiry and has no effect. Only a lender’s hard enquiry when you apply is recorded against you.": "ନା। ନିଜ ରିପୋର୍ଟ ଦେଖିବା ଏକ ସଫ୍ଟ ଅନୁସନ୍ଧାନ ଓ ତାହାର କୌଣସି ପ୍ରଭାବ ନାହିଁ। କେବଳ ଆବେଦନ କଲାବେଳେ ଋଣଦାତାଙ୍କ ହାର୍ଡ ଅନୁସନ୍ଧାନ ଆପଣଙ୍କ ନାମରେ ରେକର୍ଡ ହୁଏ।",
  "No. Credit life cover is optional on the products listed here, and a lender may not make a loan conditional on buying it.": "ନା। ଏଠାରେ ତାଲିକାଭୁକ୍ତ ଉତ୍ପାଦରେ କ୍ରେଡିଟ ଲାଇଫ କଭର ଐଚ୍ଛିକ, ଓ ଋଣଦାତା ତାହା କିଣିବା ସର୍ତ୍ତରେ ଋଣ ଦେଇପାରିବେ ନାହିଁ।",
  "No. Lenders value net gold content by weight and purity. Stones, enamel and other materials are excluded.": "ନା। ଋଣଦାତା ଓଜନ ଓ ଶୁଦ୍ଧତା ଅନୁସାରେ ନିଟ୍ ସୁନାର ମୂଲ୍ୟ ନିର୍ଦ୍ଧାରଣ କରନ୍ତି। ପଥର, ମୀନାକାରୀ ଓ ଅନ୍ୟ ସାମଗ୍ରୀ ବାଦ।",
  "No. The content here is educational. Nothing on the platform is a personal recommendation.": "ନା। ଏଠାରେ ଥିବା ବିଷୟବସ୍ତୁ ଶିକ୍ଷାମୂଳକ। ପ୍ଲାଟଫର୍ମରେ କିଛି ବି ବ୍ୟକ୍ତିଗତ ସୁପାରିଶ ନୁହେଁ।",
  "Non-repayment leads to auction of the ornaments": "ପରିଶୋଧ ନ କଲେ ଅଳଙ୍କାରର ନିଲାମ ହୁଏ",
