  "Often nil or low for domestic courses; overseas loans may attract a charge.": "ଦେଶୀୟ ପାଠ୍ୟକ୍ରମ ପାଇଁ ପ୍ରାୟତଃ ଶୂନ୍ୟ କିମ୍ବା କମ; ବିଦେଶୀ ଋଣରେ ଶୁଳ୍କ ଲାଗିପାରେ।",
  "Often nil or nominal.": "ପ୍ରାୟତଃ ଶୂନ୍ୟ କିମ୍ବା ନାମମାତ୍ର।",
  "Often, yes — particularly if you hold a competing written offer, or have an existing relationship with the lender.": "ପ୍ରାୟତଃ, ହଁ — ବିଶେଷକରି ଯଦି ଆପଣଙ୍କ ପାଖରେ ପ୍ରତିଯୋଗୀ ଲିଖିତ ଅଫର ଅଛି, କିମ୍ବା ଋଣଦାତାଙ୍କ ସହ ପୁରୁଣା ସମ୍ପର୍କ ଅଛି।",
  "old tax regime": "ପୁରୁଣା କର ବ୍ୟବସ୍ଥା",
