  "On-road price includes registration and insurance, which the loan may not fully cover": "ଅନ-ରୋଡ ମୂଲ୍ୟରେ ପଞ୍ଜୀକରଣ ଓ ବୀମା ଅନ୍ତର୍ଭୁକ୍ତ, ଯାହା ଋଣ ସମ୍ପୂର୍ଣ୍ଣ କଭର ନ କରିପାରେ",
  "One EMI and one due date instead of several": "ଅନେକ ବଦଳରେ ଗୋଟିଏ EMI ଓ ଗୋଟିଏ ଦେୟ ତାରିଖ",
  "One International Center, Tower 3, Senapati Bapat Marg, Mumbai 400013": "ୱାନ ଇଣ୍ଟରନ୍ୟାସନାଲ ସେଣ୍ଟର, ଟାୱାର 3, ସେନାପତି ବାପଟ ମାର୍ଗ, ମୁମ୍ବାଇ 400013",
  "One sum insured shared across the family. Usually cheaper than separate policies, but a single large claim can exhaust it for everyone.": "ଏକ ବୀମା ରାଶି ସମଗ୍ର ପରିବାରରେ ବାଣ୍ଟା। ଅଲଗା ପଲିସିଠାରୁ ସାଧାରଣତଃ ଶସ୍ତା, କିନ୍ତୁ ଗୋଟିଏ ବଡ଼ ଦାବି ସମସ୍ତଙ୍କ ପାଇଁ ତାହା ଶେଷ କରିଦେଇପାରେ।",
  "One upload, shared securely with your chosen lender. We chase the follow-up queries so you do not have to.": "ଥରେ ଅପଲୋଡ, ଆପଣଙ୍କ ବଛା ଋଣଦାତାଙ୍କ ସହ ସୁରକ୍ଷିତ ଭାବରେ ସେୟାର। ପରବର୍ତ୍ତୀ ପ୍ରଶ୍ନର ଅନୁସରଣ ଆମେ କରୁ, ଆପଣଙ୍କୁ କରିବାକୁ ପଡ଼େ ନାହିଁ।",
