  "Several applications in a short window create multiple hard enquiries. Check eligibility first — a soft check costs you nothing.": "ଅଳ୍ପ ସମୟରେ ଅନେକ ଆବେଦନ ଅନେକ ହାର୍ଡ ଅନୁସନ୍ଧାନ ସୃଷ୍ଟି କରେ। ପ୍ରଥମେ ଯୋଗ୍ୟତା ଯାଞ୍ଚ କରନ୍ତୁ — ସଫ୍ଟ ଯାଞ୍ଚରେ ଆପଣଙ୍କର କିଛି ଯାଏ ନାହିଁ।",
  "Several hard enquiries in a short period can suggest credit stress. Soft enquiries, such as eligibility checks here, do not count.": "ଅଳ୍ପ ସମୟରେ ଅନେକ ହାର୍ଡ ଅନୁସନ୍ଧାନ କ୍ରେଡିଟ ଚାପର ସଙ୍କେତ ଦେଇପାରେ। ଏଠାର ଯୋଗ୍ୟତା ଯାଞ୍ଚ ପରି ସଫ୍ଟ ଅନୁସନ୍ଧାନ ଗଣାଯାଏ ନାହିଁ।",
