  "Some lenders allow it with proper documentation and valuation, though dealer purchases are generally simpler to fund.": "କିଛି ଋଣଦାତା ଉପଯୁକ୍ତ ଦଲିଲ ଓ ମୂଲ୍ୟାଙ୍କନ ସହିତ ଏହାକୁ ଅନୁମତି ଦିଅନ୍ତି, ଯଦିଓ ଡିଲରଙ୍କଠାରୁ କ୍ରୟରେ ଅର୍ଥାୟନ ସାଧାରଣତଃ ସହଜ।",
  "Some lenders charge a small fee on an unused limit.": "କିଛି ଋଣଦାତା ଅବ୍ୟବହୃତ ସୀମା ଉପରେ ଛୋଟ ଶୁଳ୍କ ନିଅନ୍ତି।",
  "Some lenders require construction to start within a fixed period": "କିଛି ଋଣଦାତା ନିର୍ଦ୍ଦିଷ୍ଟ ଅବଧି ମଧ୍ୟରେ ନିର୍ମାଣ ଆରମ୍ଭ କରିବା ଆବଶ୍ୟକ କରନ୍ତି",
  "Some lenders require credit life cover on larger loans.": "କିଛି ଋଣଦାତା ବଡ଼ ଋଣରେ କ୍ରେଡିଟ ଲାଇଫ କଭର ମାଗନ୍ତି।",
  "Some schemes specifically target early-stage enterprises": "କିଛି ଯୋଜନା ବିଶେଷ ଭାବରେ ପ୍ରାରମ୍ଭିକ ପର୍ଯ୍ୟାୟର ଉଦ୍ୟୋଗ ପାଇଁ",
  "Something else": "ଅନ୍ୟ କିଛି",
  "Sort by": "ଅନୁସାରେ ସଜାନ୍ତୁ",
  "Sort by what matters to you. The cheapest headline rate is not always the cheapest loan once fees are counted.": "ଆପଣଙ୍କ ପାଇଁ ଯାହା ମହତ୍ତ୍ୱପୂର୍ଣ୍ଣ ସେହି ଅନୁସାରେ ସଜାନ୍ତୁ। ଶୁଳ୍କ ଗଣିଲେ ସର୍ବନିମ୍ନ ମୁଖ୍ୟ ହାର ସର୍ବଦା ସବୁଠାରୁ ଶସ୍ତା ଋଣ ନୁହେଁ।",
  "South": "ଦକ୍ଷିଣ",
  "South Indian Bank": "ସାଉଥ ଇଣ୍ଡିଆନ ବ୍ୟାଙ୍କ",
