  "Space out credit applications.": "କ୍ରେଡିଟ ଆବେଦନ ମଧ୍ୟରେ ବ୍ୟବଧାନ ରଖନ୍ତୁ।",
  "Speak to a support specialist": "ସହାୟତା ବିଶେଷଜ୍ଞଙ୍କ ସହ କଥା ହୁଅନ୍ତୁ",
  "Special categories": "ବିଶେଷ ବର୍ଗ",
