  "Speed": "ଗତି",
  "Speed can encourage borrowing more than needed": "ଦ୍ରୁତତା ଆବଶ୍ୟକତାଠାରୁ ଅଧିକ ଋଣ ନେବାକୁ ପ୍ରୋତ୍ସାହିତ କରିପାରେ",
