  "Spreading across assets so a single failure does not dominate the outcome.": "ସମ୍ପତ୍ତିରେ ବିସ୍ତାର, ଯେପରି ଗୋଟିଏ ବିଫଳତା ଫଳାଫଳରେ ପ୍ରାଧାନ୍ୟ ନ ପାଏ।",
  "Spreads a large one-off cost across manageable instalments": "ବଡ଼ ଏକକାଳୀନ ଖର୍ଚ୍ଚକୁ ସହଜ କିସ୍ତିରେ ବାଣ୍ଟେ",
