  "Subject to the property value and existing loan": "ସମ୍ପତ୍ତି ମୂଲ୍ୟ ଓ ବର୍ତ୍ତମାନର ଋଣ ଅନୁସାରେ",
  "Submit Application": "ଆବେଦନ ଦାଖଲ କରନ୍ତୁ",
  "Submit KYC and income proof a single time. We share it securely with your chosen lender.": "KYC ଓ ଆୟ ପ୍ରମାଣ ଥରେ ଦାଖଲ କରନ୍ତୁ। ଆମେ ତାହା ସୁରକ୍ଷିତ ଭାବରେ ଆପଣଙ୍କ ବଛା ଋଣଦାତାଙ୍କ ସହ ସେୟାର କରୁ।",
