  "Submitting does not create a loan application and has no effect on your credit score.": "ଦାଖଲ କଲେ ଋଣ ଆବେଦନ ସୃଷ୍ଟି ହୁଏ ନାହିଁ ଓ ଆପଣଙ୍କ କ୍ରେଡିଟ ସ୍କୋର ଉପରେ ପ୍ରଭାବ ପଡ଼େ ନାହିଁ।",
  "Sufficient remaining tenure for the saving to be worthwhile": "ସଞ୍ଚୟ ଅର୍ଥପୂର୍ଣ୍ଣ ହେବା ପାଇଁ ଯଥେଷ୍ଟ ବଳକା ଅବଧି",
  "Suited to larger amounts such as tuition. Compare the rate margin, not just the fee.": "ଟ୍ୟୁସନ ପରି ବଡ଼ ପରିମାଣ ପାଇଁ ଉପଯୁକ୍ତ। କେବଳ ଶୁଳ୍କ ନୁହେଁ, ହାର ମାର୍ଜିନ ତୁଳନା କରନ୍ତୁ।",
