  "Tangible and usable as jewellery, but carries making charges, storage cost and purity risk.": "ମୂର୍ତ୍ତ ଓ ଅଳଙ୍କାର ଭାବରେ ବ୍ୟବହାରଯୋଗ୍ୟ, କିନ୍ତୁ ଏଥିରେ ମେକିଂ ଚାର୍ଜ, ସଂରକ୍ଷଣ ଖର୍ଚ୍ଚ ଓ ଶୁଦ୍ଧତା ବିପଦ ରହେ।",
