  "We pull live offers from every partner whose policy fits, then take the strongest one back to the others to negotiate.": "ଯେଉଁମାନଙ୍କ ନୀତି ମେଳ ଖାଏ ସେହି ସମସ୍ତ ସହଭାଗୀଙ୍କଠାରୁ ଆମେ ଲାଇଭ ଅଫର ନେଉ, ତା’ପରେ ସବୁଠାରୁ ଶକ୍ତିଶାଳୀଟି ନେଇ ଅନ୍ୟମାନଙ୍କ ସହ ଦରକଷାକଷି କରୁ।",
  "We show what a loan costs in total and what happens if you cannot repay, not only what you could borrow.": "ଆମେ ଦେଖାଉ ଯେ ଋଣର ମୋଟ ଖର୍ଚ୍ଚ କେତେ ଓ ପରିଶୋଧ ନ କରିପାରିଲେ କ’ଣ ହୁଏ, କେବଳ ଆପଣ କେତେ ଋଣ ନେଇପାରିବେ ତାହା ନୁହେଁ।",
  "We take your best competing offer back to the other lenders. On larger tickets this routinely moves the rate by 30–70 basis points.": "ଆମେ ଆପଣଙ୍କ ସର୍ବୋତ୍ତମ ପ୍ରତିଯୋଗୀ ଅଫର ଅନ୍ୟ ଋଣଦାତାଙ୍କ ପାଖକୁ ନେଉ। ବଡ଼ ରାଶିରେ ଏଥିରେ ହାର ସାଧାରଣତଃ 30–70 ବେସିସ ପଏଣ୍ଟ ବଦଳେ।",
