  "What working with an advisor looks like": "ପରାମର୍ଶଦାତାଙ୍କ ସହ କାମ କରିବା କିପରି",
  "What would the EMI look like?": "EMI କିପରି ହେବ?",
  "What you are paying in expense ratios and charges across the whole portfolio.": "ସମ୍ପୂର୍ଣ୍ଣ ପୋର୍ଟଫୋଲିଓରେ ଆପଣ ଖର୍ଚ୍ଚ ଅନୁପାତ ଓ ଶୁଳ୍କରେ କ’ଣ ଦେଉଛନ୍ତି।",
  "What you have already been told, and by whom.": "ଆପଣଙ୍କୁ ପୂର୍ବରୁ କ’ଣ କୁହାଯାଇଛି, ଏବଂ କିଏ କହିଛନ୍ତି।",
  "What you need in place to buy shares directly, and what direct investing demands of you.": "ସିଧାସଳଖ ଶେୟାର କିଣିବା ପାଇଁ କ’ଣ ପ୍ରସ୍ତୁତ ରହିବା ଦରକାର, ଓ ପ୍ରତ୍ୟକ୍ଷ ବିନିଯୋଗ ଆପଣଙ୍କଠାରୁ କ’ଣ ମାଗେ।",
  "What you own": "ଆପଣଙ୍କ ସମ୍ପତ୍ତି",
  "What you will find in it": "ଏଥିରେ ଆପଣ କ’ଣ ପାଇବେ",
  "When does repayment start?": "ପରିଶୋଧ କେବେ ଆରମ୍ଭ ହୁଏ?",
  "Where the complaint concerns a loan or policy, the provider has its own grievance process and nodal officer.": "ଅଭିଯୋଗ ଋଣ କିମ୍ବା ପଲିସି ସମ୍ପର୍କିତ ହେଲେ, ପ୍ରଦାନକାରୀଙ୍କ ନିଜର ଅଭିଯୋଗ ପ୍ରକ୍ରିୟା ଓ ନୋଡାଲ ଅଧିକାରୀ ଅଛନ୍ତି।",
  "Where things live": "ଜିନିଷ କେଉଁଠି ଅଛି",
  "Where to find your application status, documents and repayment information.": "ଆପଣଙ୍କ ଆବେଦନ ସ୍ଥିତି, ଦଲିଲ ଓ ପରିଶୋଧ ସୂଚନା କେଉଁଠି ମିଳିବ।",
  "Where to look": "କେଉଁଠି ଦେଖିବେ",
