  "Where we lend and settle": "ଆମେ କେଉଁଠି ଋଣ ଦେଉ ଓ ନିଷ୍ପତ୍ତି କରୁ",
  "Where you can find us": "ଆପଣ ଆମକୁ କେଉଁଠି ପାଇବେ",
  "Whether day-care procedures and pre- and post-hospitalisation costs are covered.": "ଡେ-କେୟାର ପ୍ରକ୍ରିୟା ଓ ଡାକ୍ତରଖାନା ପୂର୍ବ ଓ ପରବର୍ତ୍ତୀ ଖର୍ଚ୍ଚ କଭର ହୁଏ କି।",
  "Whether it is a direct plan or a regular plan. Direct plans carry no distributor commission and therefore a lower expense ratio.": "ଏହା ଡାଇରେକ୍ଟ ପ୍ଲାନ ନା ରେଗୁଲାର ପ୍ଲାନ। ଡାଇରେକ୍ଟ ପ୍ଲାନରେ ବିତରକ କମିଶନ ନଥାଏ ଓ ସେଥିପାଇଁ ବ୍ୟୟ ଅନୁପାତ କମ।",
  "Whether one holding, sector or fund house dominates more than you realised.": "କୌଣସି ଗୋଟିଏ ହୋଲ୍ଡିଂ, କ୍ଷେତ୍ର କିମ୍ବା ଫଣ୍ଡ ହାଉସ ଆପଣଙ୍କ ଧାରଣାଠାରୁ ଅଧିକ ପ୍ରାଧାନ୍ୟ ପାଉଛି କି।",
  "Whether pre-existing conditions are covered, and on what terms.": "ପୂର୍ବରୁ ଥିବା ରୋଗ କଭର ହୁଏ କି, ଓ କେଉଁ ସର୍ତ୍ତରେ।",
  "Whether the risk level genuinely matches your horizon and your tolerance for a fall.": "ବିପଦ ସ୍ତର ପ୍ରକୃତରେ ଆପଣଙ୍କ ଅବଧି ଓ ପତନ ସହିବା କ୍ଷମତା ସହିତ ମେଳ ଖାଏ କି ନାହିଁ।",
  "Whether you can repay early without penalty affects the real cost if your circumstances change.": "ଦଣ୍ଡ ବିନା ଶୀଘ୍ର ପରିଶୋଧ କରିପାରିବା, ପରିସ୍ଥିତି ବଦଳିଲେ ପ୍ରକୃତ ଖର୍ଚ୍ଚକୁ ପ୍ରଭାବିତ କରେ।",
  "Whether you need it": "ଆପଣଙ୍କୁ ଏହା ଦରକାର କି",
  "Whether your mix has drifted away from what you intended as markets moved.": "ବଜାର ବଦଳିବାରୁ ଆପଣଙ୍କ ମିଶ୍ରଣ ଆପଣଙ୍କ ଉଦ୍ଦେଶ୍ୟରୁ ଦୂରେଇ ଯାଇଛି କି।",
  "Which documents do I need?": "ମୋତେ କେଉଁ ଦଲିଲ ଦରକାର?",
  "Which funds qualify?": "କେଉଁ ଫଣ୍ଡ ଯୋଗ୍ୟ?",
  "Which score do lenders use?": "ଋଣଦାତା କେଉଁ ସ୍କୋର ବ୍ୟବହାର କରନ୍ତି?",
  "Which suits you": "ଆପଣଙ୍କ ପାଇଁ କେଉଁଟି ଉପଯୁକ୍ତ",
  "Who benefits": "କାହାର ଲାଭ",
  "Who can apply for a loan?": "ଋଣ ପାଇଁ କିଏ ଆବେଦନ କରିପାରିବେ?",
  "Who compiles your credit record, and why your score can differ between them.": "ଆପଣଙ୍କ କ୍ରେଡିଟ ରେକର୍ଡ କିଏ ପ୍ରସ୍ତୁତ କରେ, ଓ ସେମାନଙ୍କ ମଧ୍ୟରେ ଆପଣଙ୍କ ସ୍କୋର କାହିଁକି ଭିନ୍ନ ହୋଇପାରେ।",
  "Who it suits": "ଏହା କାହା ପାଇଁ",
  "Who qualifies": "ଯୋଗ୍ୟତା",
  "Who we work with": "ଆମେ କାହା ସହ କାମ କରୁ",
  "Why applicants choose": "ଆବେଦନକାରୀ କାହିଁକି ବାଛନ୍ତି",
