  "Why is it more expensive than a secured loan?": "ଏହା ସୁରକ୍ଷିତ ଋଣଠାରୁ ମହଙ୍ଗା କାହିଁକି?",
  "Why is my rate higher than the advertised one?": "ମୋର ହାର ବିଜ୍ଞାପିତ ହାରଠାରୁ ଅଧିକ କାହିଁକି?",
  "Why is my score different on two bureaus?": "ଦୁଇ ବ୍ୟୁରୋରେ ମୋର ସ୍କୋର ଭିନ୍ନ କାହିଁକି?",
  "Why it helps": "ଏହା କାହିଁକି ସହାୟକ",
  "Why seeing everything in one place changes the decisions you make.": "ସବୁକିଛି ଗୋଟିଏ ସ୍ଥାନରେ ଦେଖିଲେ ଆପଣଙ୍କ ନିଷ୍ପତ୍ତି କାହିଁକି ବଦଳେ।",
  "Why the platform exists and how it is paid.": "ପ୍ଲାଟଫର୍ମ କାହିଁକି ଅଛି ଓ ଏହା କିପରି ପାରିଶ୍ରମିକ ପାଏ।",
  "Why the platform exists and what it is trying to do.": "ପ୍ଲାଟଫର୍ମ କାହିଁକି ଅଛି ଓ ଏହା କ’ଣ କରିବାକୁ ଚେଷ୍ଟା କରୁଛି।",
  "Why use this platform": "ଏହି ପ୍ଲାଟଫର୍ମ କାହିଁକି",
