  "Wide network of trusted partners": "ବିଶ୍ୱସ୍ତ ଭାଗିଦାରଙ୍କ ବ୍ୟାପକ ନେଟୱାର୍କ",
  "Will anyone ask for my OTP or PIN?": "କେହି ମୋର OTP କିମ୍ବା PIN ମାଗିବେ କି?",
  "Will consolidating improve my credit score?": "ଏକତ୍ରୀକରଣ ମୋର କ୍ରେଡିଟ ସ୍କୋର ଉନ୍ନତ କରିବ କି?",
  "Will my current lender match the rate?": "ମୋର ବର୍ତ୍ତମାନର ଋଣଦାତା ସେହି ହାର ଦେବେ କି?",
  "Will my EMI change automatically?": "ମୋର EMI ସ୍ୱୟଂଚାଳିତ ଭାବରେ ବଦଳିବ କି?",
  "Willingness to begin construction within the lender’s timeframe, where required": "ଆବଶ୍ୟକ ହେଲେ ଋଣଦାତାଙ୍କ ସମୟସୀମା ମଧ୍ୟରେ ନିର୍ମାଣ ଆରମ୍ଭ କରିବାର ପ୍ରସ୍ତୁତି",
  "Wire transfer": "ୱାୟାର ଟ୍ରାନ୍ସଫର",
  "With the bureau, and follow up with the lender that reported it.": "ବ୍ୟୁରୋ ପାଖରେ, ଓ ଯେଉଁ ଋଣଦାତା ରିପୋର୍ଟ କରିଛନ୍ତି ତାଙ୍କ ସହ ଅନୁସରଣ କରନ୍ତୁ।",
  "within one working day.": "ଏକ କାର୍ଯ୍ୟ ଦିବସ ମଧ୍ୟରେ।",
  "Work it out in five steps": "ପାଞ୍ଚ ପାହାଚରେ ହିସାବ କରନ୍ତୁ",
  "Work out the total repayable": "ମୋଟ ପରିଶୋଧଯୋଗ୍ୟ ପରିମାଣ ବାହାର କରନ୍ତୁ",
  "Work out what you need": "ଆପଣଙ୍କୁ କ’ଣ ଦରକାର ସ୍ଥିର କରନ୍ତୁ",
  "Working capital": "କାର୍ଯ୍ୟକାରୀ ପୁଞ୍ଜି",
  "Working Capital": "କାର୍ଯ୍ୟକାରୀ ପୁଞ୍ଜି",
  "Working capital and expansion finance.": "କାର୍ଯ୍ୟକାରୀ ପୁଞ୍ଜି ଓ ବିସ୍ତାର ଅର୍ଥ।",
  "Working Capital Loan": "କାର୍ଯ୍ୟକାରୀ ପୁଞ୍ଜି ଋଣ",
  "Working capital to buy raw material and manufacture against a confirmed export order.": "ନିଶ୍ଚିତ ରପ୍ତାନି ଅର୍ଡର ବିରୋଧରେ କଞ୍ଚାମାଲ କିଣିବା ଓ ଉତ୍ପାଦନ ପାଇଁ କାର୍ଯ୍ୟକାରୀ ପୁଞ୍ଜି।",
  "Working capital to grow your business.": "ଆପଣଙ୍କ ବ୍ୟବସାୟ ବୃଦ୍ଧି ପାଇଁ କାର୍ଯ୍ୟକାରୀ ପୁଞ୍ଜି।",
  "Working capital, expansion and equipment finance for businesses.": "ବ୍ୟବସାୟ ପାଇଁ କାର୍ଯ୍ୟକାରୀ ପୁଞ୍ଜି, ବିସ୍ତାର ଓ ଉପକରଣ ଅର୍ଥ।",
  "Working capital, machinery and commercial vehicle finance, including OD and invoice-backed lines.": "କାର୍ଯ୍ୟକାରୀ ପୁଞ୍ଜି, ଯନ୍ତ୍ରପାତି ଓ ବାଣିଜ୍ୟିକ ଯାନ ଅର୍ଥାୟନ, OD ଓ ଇନଭଏସ-ଆଧାରିତ ଲାଇନ ସହିତ।",
  "Working capital, stock and equipment.": "କାର୍ଯ୍ୟକାରୀ ପୁଞ୍ଜି, ଷ୍ଟକ୍ ଓ ଉପକରଣ।",
  "Year": "ବର୍ଷ",
  "Year by year, how much goes to principal and how much to interest": "ବର୍ଷ ବର୍ଷ, କେତେ ମୂଳଧନରେ ଓ କେତେ ସୁଧରେ ଯାଏ",
  "Year,Principal paid,Interest paid,Total paid,Balance at year end\n": "ବର୍ଷ,ପରିଶୋଧିତ ମୂଳଧନ,ପରିଶୋଧିତ ସୁଧ,ମୋଟ ପରିଶୋଧ,ବର୍ଷଶେଷରେ ବାକି\n",
  "Years in current job": "ବର୍ତ୍ତମାନ ଚାକିରିରେ ବର୍ଷ",
  "Yes, ongoing SIPs generally continue. Only the specific units under lien are restricted.": "ହଁ, ଚାଲୁଥିବା SIP ସାଧାରଣତଃ ଜାରି ରହେ। କେବଳ ବନ୍ଧକ ଥିବା ନିର୍ଦ୍ଦିଷ୍ଟ ୟୁନିଟ ହିଁ ପ୍ରତିବନ୍ଧିତ।",
  "You are entitled to access your report and to dispute entries you believe are wrong.": "ଆପଣଙ୍କର ରିପୋର୍ଟ ଦେଖିବା ଓ ଭୁଲ ମନେ ହେଉଥିବା ଏଣ୍ଟ୍ରି ଉପରେ ଆପତ୍ତି କରିବାର ଅଧିକାର ଆପଣଙ୍କର ଅଛି।",
  "You are notified and pay manually. A middle path where amounts vary a lot.": "ଆପଣଙ୍କୁ ସୂଚନା ମିଳେ ଓ ଆପଣ ନିଜେ ପେମେଣ୍ଟ କରନ୍ତି। ଯେଉଁଠି ରାଶି ବହୁତ ବଦଳେ, ସେଠାରେ ମଝି ବାଟ।",
